import React, { useState, useEffect } from 'react';
import api from '../services/api';
import Card from '../components/Card';
import Button from '../components/Button';
import Input from '../components/Input';
import Modal from '../components/Modal';

function Ministries() {
  const [ministries, setMinistries] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ name: '', description: '' });

  useEffect(() => { loadData(); }, []);

  const loadData = async () => {
    const res = await api.get('/ministries.php');
    setMinistries(res.data);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    await api.post('/ministries.php', form);
    setShowForm(false);
    loadData();
  };

  return (
    <div style={{ maxWidth: 800, margin: '0 auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 20 }}>
        <h1>Ministerios</h1>
        <Button onClick={() => setShowForm(true)}>Novo Ministerio</Button>
      </div>
      {ministries.map(m => (
        <Card key={m.id} style={{ marginBottom: 10 }}>
          <strong>{m.name}</strong>
          <p>{m.description}</p>
        </Card>
      ))}
      <Modal isOpen={showForm} onClose={() => setShowForm(false)} title="Novo Ministerio">
        <form onSubmit={handleSubmit}>
          <Input label="Nome" value={form.name} onChange={e => setForm({...form, name: e.target.value})} />
          <Input label="Descricao" value={form.description} onChange={e => setForm({...form, description: e.target.value})} />
          <Button type="submit">Salvar</Button>
        </form>
      </Modal>
    </div>
  );
}
export default Ministries;
